import type { ComponentProps } from "@solidjs/web";
import { cn } from "~/lib/utils.ts";
import type { Component } from "solid-js";

import { omit } from "solid-js";

const Card: Component<ComponentProps<"div"> & { size?: "default" | "sm" }> = (props) => {
  const others = omit(props, "class", "size");
  return (
    <div
      data-slot="card"
      data-size={props.size ?? "default"}
      class={cn("bg-card text-card-foreground ring-foreground/5 gap-(--card-spacing) overflow-hidden py-(--card-spacing) text-sm shadow-sm ring-1 [--card-spacing:--spacing(8)] has-[>img:first-child]:pt-0 data-[size=sm]:[--card-spacing:--spacing(5)] *:[img:first-child]:rounded-none *:[img:last-child]:rounded-none group/card flex flex-col", props.class)}
      {...others}
    />
  );
};

const CardHeader: Component<ComponentProps<"div">> = (props) => {
  const others = omit(props, "class");
  return (
    <div
      data-slot="card-header"
      class={cn(
        "@container/card-header gap-1.5 rounded-none px-(--card-spacing) [.border-b]:pb-(--card-spacing) group/card-header grid auto-rows-min items-start has-data-[slot=card-action]:grid-cols-[1fr_auto] has-data-[slot=card-description]:grid-rows-[auto_auto]",
        props.class,
      )}
      {...others}
    />
  );
};

const CardTitle: Component<ComponentProps<"div">> = (props) => {
  const others = omit(props, "class");
  return (
    <div data-slot="card-title" class={cn("text-lg font-semibold tracking-wider uppercase font-heading", props.class)} {...others} />
  );
};

const CardDescription: Component<ComponentProps<"div">> = (props) => {
  const others = omit(props, "class");
  return (
    <div data-slot="card-description" class={cn("text-muted-foreground text-sm leading-relaxed", props.class)} {...others} />
  );
};

const CardAction: Component<ComponentProps<"div">> = (props) => {
  const others = omit(props, "class");
  return (
    <div
      data-slot="card-action"
      class={cn(
        "col-start-2 row-span-2 row-start-1 self-start justify-self-end",
        props.class,
      )}
      {...others}
    />
  );
};

const CardContent: Component<ComponentProps<"div">> = (props) => {
  const others = omit(props, "class");
  return <div data-slot="card-content" class={cn("px-(--card-spacing)", props.class)} {...others} />;
};

const CardFooter: Component<ComponentProps<"div">> = (props) => {
  const others = omit(props, "class");
  return (
    <div
      data-slot="card-footer"
      class={cn("px-(--card-spacing) [.border-t]:pt-(--card-spacing) flex items-center", props.class)}
      {...others}
    />
  );
};

export { Card, CardAction, CardContent, CardDescription, CardFooter, CardHeader, CardTitle };
